<?php
namespace App\Http\Controllers;
use App\Exports\TrainingAnalyticsExport;use App\Models\{PerfilEmpresa,TrainingAlert};use App\Services\{TrainingGapService,TrainingIndicatorService,TrainingStandardsEvidenceService};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class TrainingReportController extends Controller{private function data(Request$r,TrainingIndicatorService$i,TrainingGapService$g,TrainingStandardsEvidenceService$e):array{$companyId=$r->user()->company_id;$year=(int)$r->input('year',now()->year);return['company'=>PerfilEmpresa::findOrFail($companyId),'year'=>$year,'metrics'=>$i->forCompany($companyId,$year),'gaps'=>$g->summary($companyId),'alerts'=>TrainingAlert::forCompany($companyId)->whereIn('status',['open','acknowledged'])->limit(20)->get(),'evidence'=>$e->getAvailableEvidence($companyId,$year)];}public function pdf(Request$r,TrainingIndicatorService$i,TrainingGapService$g,TrainingStandardsEvidenceService$e){return Pdf::loadView('pdf.training_management',$this->data($r,$i,$g,$e))->setPaper('letter')->download('informe-gestion-capacitaciones.pdf');}public function excel(Request$r,TrainingIndicatorService$i,TrainingGapService$g,TrainingStandardsEvidenceService$e){$d=$this->data($r,$i,$g,$e);$m=$d['metrics'];$rows=[['Ejecución del programa',$m['program_execution']['numerator'],$m['program_execution']['denominator'],$m['program_execution']['value']],['Cobertura',$m['coverage']['numerator'],$m['coverage']['denominator'],$m['coverage']['value']],['Evaluación',$m['evaluation']['numerator'],$m['evaluation']['denominator'],$m['evaluation']['value']],['Aprobación',$m['approval']['numerator'],$m['approval']['denominator'],$m['approval']['value']],['Refuerzos completados',$m['reinforcement']['numerator'],$m['reinforcement']['denominator'],$m['reinforcement']['value']],['Necesidades atendidas',$m['needs_attended']['numerator'],$m['needs_attended']['denominator'],$m['needs_attended']['value']]];return Excel::download(new TrainingAnalyticsExport($rows,['Indicador','Numerador','Denominador','Porcentaje'],'Indicadores'),'indicadores-capacitacion-'.$d['year'].'.xlsx');}}
